import{_ as a,o as t,c as l,a5 as o}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"三、搭建服务提供者","description":"","frontmatter":{"title":"三、搭建服务提供者","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","微服务","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/三、搭建服务提供者.md","filePath":"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/三、搭建服务提供者.md"}'),r={name:"posts/java快速入门/第九部分：微服务/01-微服务入门/微服务入门级教程/三、搭建服务提供者.md"};function i(p,e,n,c,s,d){return t(),l("div",null,[...e[0]||(e[0]=[o('<div><p>服务提供者，往往就是我们项目里真正要提供API接口的部分，也就是我们的业务代码。</p><p>由于我们这里只是示例，所以不牵扯数据库，controller层直接返回模拟数据。 我们把项目叫做role</p><p>主要选择以下几个依赖：</p><p>注意要选上Eureka Discovery Client，可以使我们的项目拥有注册到Eureka服务中心的能力。 接下来点create;</p><p>然后，我们创建一个实体类和一个Controller控制器：</p><p>修改配置文件：</p><ul><li>server:</li><li>port: 8081</li><li><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>应用名称：</p><ul><li>client</li><li>spring:</li><li>application:</li><li>name: client</li><li><h1 id="-1" tabindex="-1"><a class="header-anchor" href="#-1" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>注册到我们本地的<code>eureka</code>注册中心，端口是</p><p>8080 eureka: client: service-url: defaultZone: <a href="http://localhost:8080/eureka/" target="_blank" rel="noreferrer">http://localhost:8080/eureka/</a></p><p>import com.mincheng.role.entity.RoleEntity; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.RequestMapping; import org.springframework.web.bind.annotation.RestController; @RestController @RequestMapping(value = &quot;/role&quot;) public class RoleController {</p><p>@GetMapping(value = &quot;/detail&quot;) public Object getRole() { RoleEntity role = new RoleEntity(); // 可以看到，我们没有在实体类写<code>get</code>和<code>set</code>方法，但是我们依然可以调用这些方法 <code>//</code>这就是<code>Lombok</code>插件的好处，只需要在实体类加一个<code>@Data</code>注解 <code>role.setName(&quot;</code>张三</p><p>&quot;); role.setAge(18); return role; } }</p><p>然后我们修改一下这个项目的application.yml：</p><ul><li>server:</li><li>port: 8081</li><li><h1 id="-2" tabindex="-1"><a class="header-anchor" href="#-2" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>应用名称：</p><ul><li>client</li><li>spring:</li><li>application:</li><li>name: client</li><li><h1 id="-3" tabindex="-1"><a class="header-anchor" href="#-3" aria-label="Permalink to &quot;&quot;">​</a></h1></li></ul><p>注册到我们本地的<code>eureka</code>注册中心，端口是</p><p>8080 eureka: client: service-url: defaultZone: <a href="http://localhost:8080/eureka/" target="_blank" rel="noreferrer">http://localhost:8080/eureka/</a> 然后在启动类上加@EnableEurekaClient注解，表面这是一个服务提供者：</p><p>然后启动这个服务提供者，成功之后刷新注册中心页面，可以看到名叫client的服务已经注册进来(只有一个节点)：</p><p>我们访问localhost:8081/role/detail，如下：</p><p>可能有同学要说了，你不是都微服务了吗，怎么还是直接调8081端口？为什么不走服务中心啊？这样还不如我直接创建一个Spring Boot项目呢？</p><p>我们先不通过服务中心调接口，因为服务注册中心是根据服务名称去选择要进行业务处理的服务器，而通过服务名称调用接口，要么走Fegin，Ribbon的RestTemplate，这些都是需要用Java代码实现的，适用于系统内部之间的调用，不适用于直接访问的情况。如果你想直接以API接口的方式访问服务注册中心的服务并且达到负载均衡的效果，只有通过网关。网关的内容在下面，先不着急。</p></div>',1)])])}const _=a(r,[["render",i]]);export{h as __pageData,_ as default};
